package core.game.node.entity;import core.game.node.Node;import core.game.world.map.Location;public class Entity extends Node{public Entity(){super("entity",new Location(3207,3217,0));}public void lock(int ticks){oracle.Support.emit("lock",ticks);}public Location getLocation(){oracle.Support.emit("location");return location;}public void setLocation(Location l){oracle.Support.emit("setLocation",oracle.Support.coords(l));location=l;}public core.game.node.entity.player.Player asPlayer(){return(core.game.node.entity.player.Player)this;}public Walking getWalkingQueue(){return new Walking();}public static class Walking{public void reset(){oracle.Support.emit("walkReset");}public void addPath(int x,int y){oracle.Support.emit("walkAdd",x,y);}}}